import unittest
from app.domain import message
class ExpiryTests(unittest.TestCase):
    def test_structured_expiry_uses_local_text(self):
        self.assertEqual(message({'detail':{'msg_key':'PRICING_QUOTE_EXPIRED','msg':'localized server text'}}),
                         'This quote has expired. Confirm your amount again to get a new quote.')
    def test_used_preserves_structured_message(self):
        self.assertEqual(message({'detail':{'msg_key':'PRICING_QUOTE_USED','msg':'Already submitted'},'description':'pricing quote has expired'}),'Already submitted')
if __name__=='__main__':unittest.main()
